import{_ as e,c as r,o as t,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"常見問題","description":"關於價格、隱私、支援機型、資料夾、介面語言與恢復購買的解答。","frontmatter":{"title":"常見問題","description":"關於價格、隱私、支援機型、資料夾、介面語言與恢復購買的解答。"},"headers":[],"relativePath":"zh-TW/guide/faq.md","filePath":"zh-TW/guide/faq.md","lastUpdated":1793948370000}'),h={name:"zh-TW/guide/faq.md"};function o(l,a,d,n,s,c){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h1><h3 id="qdiff-免費嗎" tabindex="-1">qDiff 免費嗎？ <a class="header-anchor" href="#qdiff-免費嗎" aria-label="Permalink to &quot;qDiff 免費嗎？&quot;">​</a></h3><p>免費。所有比較、查看和匯出功能，不付費也能用。免費版只在標籤列上多一個 「未授權」小標記。一次性購買會去掉它，並包含以後新增的進階功能。沒有訂閱， 也沒有廣告。</p><h3 id="購買之後會解鎖新功能嗎" tabindex="-1">購買之後會解鎖新功能嗎？ <a class="header-anchor" href="#購買之後會解鎖新功能嗎" aria-label="Permalink to &quot;購買之後會解鎖新功能嗎？&quot;">​</a></h3><p>不會 —— 功能本來就全部可用。購買只是去掉那個小標記。以後如果增加進階能力， 也會算在同一次購買裡，不會再賣第二個商品。</p><h3 id="換電腦後怎麼恢復購買" tabindex="-1">換電腦後怎麼恢復購買？ <a class="header-anchor" href="#換電腦後怎麼恢復購買" aria-label="Permalink to &quot;換電腦後怎麼恢復購買？&quot;">​</a></h3><p>打開「設定 → 進階功能」，點「恢復購買」。購買記錄與 Apple ID 綁定，在你的 其他 Mac 上同樣有效。</p><h3 id="支援哪些-mac" tabindex="-1">支援哪些 Mac？ <a class="header-anchor" href="#支援哪些-mac" aria-label="Permalink to &quot;支援哪些 Mac？&quot;">​</a></h3><p>macOS 12 或更新版本，Apple 晶片與 Intel 機型都可以，詳見 <a href="./download.html#system-requirements">系統需求</a>。</p><h3 id="需要帳號或連網嗎" tabindex="-1">需要帳號或連網嗎？ <a class="header-anchor" href="#需要帳號或連網嗎" aria-label="Permalink to &quot;需要帳號或連網嗎？&quot;">​</a></h3><p>不需要。qDiff 離線可用，不用登入，也沒有背景服務。它只打開你選擇的檔案和 資料夾。</p><h3 id="能比較整個資料夾和壓縮檔嗎" tabindex="-1">能比較整個資料夾和壓縮檔嗎？ <a class="header-anchor" href="#能比較整個資料夾和壓縮檔嗎" aria-label="Permalink to &quot;能比較整個資料夾和壓縮檔嗎？&quot;">​</a></h3><p>能。資料夾以樹狀展開，可按狀態篩選、直接複製和同步；.zip / .tar 不用解壓， 也能當資料夾來比。</p><h3 id="圖片和不是文字的檔案呢" tabindex="-1">圖片和不是文字的檔案呢？ <a class="header-anchor" href="#圖片和不是文字的檔案呢" aria-label="Permalink to &quot;圖片和不是文字的檔案呢？&quot;">​</a></h3><p>圖片可以並排看，也可以疊加看差異；不是純文字的檔案，還能細到最小的差別。 見<a href="./more.html">更多比較方式</a>。</p><h3 id="你們會上傳或分析我的檔案嗎" tabindex="-1">你們會上傳或分析我的檔案嗎？ <a class="header-anchor" href="#你們會上傳或分析我的檔案嗎" aria-label="Permalink to &quot;你們會上傳或分析我的檔案嗎？&quot;">​</a></h3><p>不會。不收集、不追蹤、不上傳，完整說明見<a href="./../privacy/">隱私政策</a>。</p><h3 id="介面有中文嗎" tabindex="-1">介面有中文嗎？ <a class="header-anchor" href="#介面有中文嗎" aria-label="Permalink to &quot;介面有中文嗎？&quot;">​</a></h3><p>有繁體中文、簡體中文、英文等多種語言，並支援淺色與深色外觀。</p><h3 id="用的時候遇到問題怎麼辦" tabindex="-1">用的時候遇到問題怎麼辦？ <a class="header-anchor" href="#用的時候遇到問題怎麼辦" aria-label="Permalink to &quot;用的時候遇到問題怎麼辦？&quot;">​</a></h3><p><a href="./support.html">聯絡我們</a>，附上 macOS 版本和一句症狀描述就好；有截圖會更快。</p>',21)])])}const q=e(h,[["render",o]]);export{f as __pageData,q as default};
